css:
/* From Uiverse.io by Li-Deheng - Tags: animation, button, input, rounded, animated, click effect, input effect , hover button */
.__UIV_SCOPE__ .search-panels {
  --default-color: #9e9e9e;
  --color-text: #ccc;
  --color-active: #1a73e8;
  --color-active-input: #f5f5f5;
  --transition: 150ms cubic-bezier(0.4,0,0.2,1);
  --width-input: 200px;
}

.__UIV_SCOPE__ .search-group {
  position: relative;
}

.__UIV_SCOPE__ .input {
  width: var(--width-input);
  border: solid 1.5px var(--default-color);
  border-radius: 80px;
  background: none;
  padding: 1rem;
  padding-right: 3rem;
  font-size: 1rem;
  color: var(--color-active-input);
  transition: border var(--transition);
}

.__UIV_SCOPE__ .enter-label {
  position: absolute;
  left: 15px;
  color: var(--default-color);
  pointer-events: none;
  transform: translateY(1rem);
  transition: var(--transition);
}

.__UIV_SCOPE__ .enter-label {
  color: var(--default-color);
  pointer-events: none;
}

.__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ input:valid {
  outline: none;
  border: 1.5px solid var(--color-active);
}

.__UIV_SCOPE__ .input:focus ~ label, .__UIV_SCOPE__ input:valid ~ label {
  transform: translateY(-50%) scale(0.8);
  background-color: var(--color-active);
  border-radius: 20px;
  padding: .2em .6em;
  color: var(--color-text);
}

.__UIV_SCOPE__ .btn-box {
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  top: -1em;
  right: 80%;
  border-radius: 100%;
  transition: 300ms cubic-bezier(0.4,0,0.2,1);
  transition-delay: 100ms;
  opacity: 0;
}

.__UIV_SCOPE__ .input:focus ~ .btn-box, .__UIV_SCOPE__ input:valid ~ .btn-box {
  right: 10%;
  opacity: 1;
  transition-delay: 0s;
  transition: var(--transition);
}

.__UIV_SCOPE__ .input:not(:focus) ~ .btn-box, .__UIV_SCOPE__ input:not(:valid) ~ .btn-box {
  transition-property: right, opacity;
  transition-delay: 300ms;
}

.__UIV_SCOPE__ .input:focus ~ .btn-box:hover, .__UIV_SCOPE__ input:valid ~ .btn-box:hover {
  transform: scale(1.2);
}

.__UIV_SCOPE__ .input:focus ~ .btn-box:hover:active, .__UIV_SCOPE__ input:valid ~ .btn-box:hover:active {
  transform: scale(1);
}

.__UIV_SCOPE__ .btn-search {
  position: relative;
  cursor: pointer;
  background-color: var(--color-active);
  width: 2em;
  height: 2em;
  top: 2.5px;
  border: none;
  border-radius: 100%;
  padding: 0;
  transition: var(--transition);
}

.__UIV_SCOPE__ .btn-search:active {
  transform: scale(1);
}

.__UIV_SCOPE__ .btn-search svg {
  position: absolute;
  top: 25%;
  left: 25%;
  fill: var(--color-text);
  width: 12px;
  height: 12px;
}

.__UIV_SCOPE__ #svg-circle {
  fill: var(--color-text);
  transition: var(--transition);
}

.__UIV_SCOPE__ .input:focus ~ .btn-box:hover #svg-circle, .__UIV_SCOPE__ input:valid ~ .btn-box:hover #svg-circle {
  fill: transparent;
}

.__UIV_SCOPE__ .btn-box-x {
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  top: 1em;
  right: 7%;
  opacity: 0;
  transform: rotate(-90deg) scale(.1);
  transition: var(--transition);
}

.__UIV_SCOPE__ .input:focus ~ .btn-box-x, .__UIV_SCOPE__ input:valid ~ .btn-box-x {
  opacity: 1;
  transform: rotate(0) scale(1);
}

.__UIV_SCOPE__ .btn-cleare {
  position: relative;
  cursor: pointer;
  background-color: transparent;
  width: 2em;
  height: 2em;
  border: none;
  border-radius: 100%;
  padding: 0;
  transition: var(--transition);
}

.__UIV_SCOPE__ .btn-cleare svg {
  width: 15px;
  height: 15px;
}

.__UIV_SCOPE__ #cleare-line {
  fill: var(--default-color);
}

.__UIV_SCOPE__ .btn-box-x:hover #cleare-line {
  fill: var(--color-active);
}
